
const d=[{"id": "P00-01", "section": "P00", "title": "Một website có thể nhớ em?", "layout": "cover", "subtitle": "Bài học Cookies · 42 phút · gia sư 1–1", "prompt": "Hôm trước em chọn Tiếng Việt, hôm nay website vẫn hiện tiếng Việt. Điều gì có thể giúp website ghi nhớ?", "asset": "", "note": "Câu hỏi mở – chưa định nghĩa Cookie.", "learner_action": "HS nói một dự đoán trước khi bắt đầu"}, {"id": "D0-01", "section": "D0", "title": "Ai xin trang? Ai trả trang?", "layout": "diagram", "subtitle": "D0 · Chẩn đoán kiến thức nền", "prompt": "Hãy chỉ hướng xin trang và hướng trả trang giữa Browser và Server.", "asset": "browser_server_blank.svg", "note": "Không hiển thị key khi học sinh đang làm.", "learner_action": "HS đặt hai mũi tên và nêu lý do"}, {"id": "D0-02", "section": "D0", "title": "Một mẩu dữ liệu có ý nghĩa gì?", "layout": "question", "subtitle": "Từ kiến thức nền đến tình huống Cookies", "prompt": "Theo em, language=vi có thể biểu diễn thông tin gì?", "asset": "", "note": "Không cần biết thuật ngữ Cookie.", "learner_action": "HS nói suy đoán; GV ghi mức hỗ trợ"}, {"id": "A1-01", "section": "ACT01", "title": "Vì sao lần sau vẫn là tiếng Việt?", "layout": "compare", "subtitle": "ACT01 · Hiện tượng trước khái niệm", "prompt": "Quan sát hai trạng thái trước/sau khi lựa chọn ngôn ngữ. Thông tin tối thiểu cần nhớ là gì?", "asset": "", "note": "Dùng hình hai trạng thái cùng một website, không thay ngữ cảnh.", "learner_action": "HS dự đoán dữ liệu tối thiểu"}, {"id": "A1-02", "section": "ACT01", "title": "Cookie là một mẩu dữ liệu", "layout": "focus", "subtitle": "ACT01 · Kiến thức mới ngắn gọn", "prompt": "Cookie là dữ liệu nhỏ mà trình duyệt có thể quản lý cho website; nó không phải HTML hay một chương trình tự chạy.", "asset": "", "note": "Ví dụ language=vi chỉ là dữ liệu hư cấu.", "learner_action": "HS diễn giải lại bằng lời riêng"}, {"id": "A1-03", "section": "ACT01", "title": "Thẻ nào là dữ liệu ghi nhớ?", "layout": "practice", "subtitle": "ACT01 · Thử và nhớ lại", "prompt": "Phân loại: language=vi, <h1>Xin chào</h1>, run.exe. Sau đó che thẻ và nêu một việc Cookie có thể giúp.", "asset": "", "note": "Đáp án chỉ xuất hiện sau lượt thử; đây là layout prototype.", "learner_action": "HS chọn nhóm và giải thích lý do"}, {"id": "A2-01", "section": "ACT02", "title": "Bước 1 · Browser xin trang", "layout": "progressive", "subtitle": "ACT02 · Một bước mẫu", "prompt": "Lượt truy cập đầu, Browser gửi HTTP Request đến Server. Bước tiếp theo có thể là gì?", "asset": "browser_server_blank.svg", "note": "Chỉ làm mẫu request, chưa vẽ toàn bộ vòng đời.", "learner_action": "HS dự đoán bước kế tiếp"}, {"id": "A2-02", "section": "ACT02", "title": "Ai gửi Set-Cookie?", "layout": "practice", "subtitle": "ACT02 · Học sinh tự ghép", "prompt": "Hãy chọn hướng của HTTP Response có thể mang Set-Cookie: language=vi.", "asset": "", "note": "Không đưa next move ngay khi chọn sai; chỉ phản hồi về quy tắc request/response.", "learner_action": "HS đặt message và giải thích"}, {"id": "A2-03", "section": "ACT02", "title": "Browser có thể lưu hoặc từ chối", "layout": "compare", "subtitle": "ACT02 · Hai khả năng cùng một chỉ dẫn", "prompt": "Server gửi chỉ dẫn, nhưng Browser là bên quyết định có lưu cookie theo điều kiện áp dụng.", "asset": "", "note": "Không diễn đạt Server trực tiếp ghi vào bộ nhớ trình duyệt.", "learner_action": "HS dự đoán trạng thái Browser"}, {"id": "A2-04", "section": "ACT02", "title": "Lượt sau: Cookie đi hướng nào?", "layout": "progressive", "subtitle": "ACT02 · Quay lại cùng website", "prompt": "Nếu Browser có cookie còn hợp lệ và phù hợp phạm vi, cookie có thể đi trong Request từ Browser đến Server.", "asset": "cookie_lifecycle.svg", "note": "Chỉ mở sơ đồ đầy đủ sau khi học sinh đã thử. Hình ở đây minh họa bố cục giai đoạn đối chiếu.", "learner_action": "HS chọn hướng và giải thích vì sao"}, {"id": "A2-05", "section": "ACT02", "title": "Nhận Cookie và chặn Cookie", "layout": "compare", "subtitle": "ACT02 · Cùng tình huống, hai trạng thái", "prompt": "Nếu Browser không lưu cookie được đề nghị, lần sau không thể gửi lại chính cookie ấy.", "asset": "cookie_accept_block.svg", "note": "Không khẳng định website chắc chắn quên bằng mọi cơ chế khác.", "learner_action": "HS dự đoán khác biệt trước khi xem đối chiếu"}, {"id": "A2-06", "section": "ACT02", "title": "Vẽ lại hai chiều không nhìn mẫu", "layout": "recall", "subtitle": "ACT02 · Active Recall", "prompt": "Không nhìn hình: em hãy vẽ Server → Browser với Set-Cookie và Browser → Server với Cookie trong request phù hợp.", "asset": "", "note": "Chỉ hiển thị nhắc nhớ, không lộ sơ đồ chuẩn trước lượt recall.", "learner_action": "HS nói và vẽ vào vở"}, {"id": "A3-01", "section": "ACT03", "title": "Cookie nào còn vào ngày mai?", "layout": "timeline", "subtitle": "ACT03 · Quan sát thời hạn", "prompt": "Ba mốc: đang duyệt → phiên kết thúc → ngày hôm sau. Đánh dấu nơi mỗi cookie còn có thể dùng.", "asset": "", "note": "Chỉ hiện timeline không giải sẵn; học sinh dự đoán trước khi xem bản chuẩn.", "learner_action": "HS đặt thẻ session/persistent"}, {"id": "A3-02", "section": "ACT03", "title": "Đổi thời hạn, đổi loại Cookie", "layout": "compare", "subtitle": "ACT03 · Phản ví dụ", "prompt": "Nếu cart_id=C104 được thêm thời hạn 7 ngày, tên và mục đích giữ nguyên nhưng phân loại theo thời hạn thay đổi.", "asset": "session_persistent_timeline.svg", "note": "Chỉ xem hình chuẩn sau khi HS tự đoán; session restore là ngoại lệ cần nhắc đúng.", "learner_action": "HS giải thích sự thay đổi"}, {"id": "A3-03", "section": "ACT03", "title": "Hai loại khác nhau ở đâu?", "layout": "recall", "subtitle": "ACT03 · Ghi nhớ có lý do", "prompt": "Hãy nêu hai điểm khác nhau theo vòng đời và một điều kiện khiến cookie không còn.", "asset": "", "note": "Không định nghĩa bằng RAM/ổ cứng hoặc đóng tab.", "learner_action": "HS nói rồi ghi trong vở"}, {"id": "A4-01", "section": "ACT04", "title": "Ba công dụng của Cookie", "layout": "trio", "subtitle": "ACT04 · Phân loại tình huống", "prompt": "SHOP – giỏ hàng; LANGUAGE – lựa chọn ngôn ngữ; ANALYTICS – phân tích lượt xem. Hãy ghép với mục đích phù hợp.", "asset": "", "note": "Ba thẻ cùng ngữ cảnh và mức thông tin tương đương.", "learner_action": "HS phân nhóm và nêu nguyên nhân"}, {"id": "A4-02", "section": "ACT04", "title": "Sống lâu có phải là tracking?", "layout": "compare", "subtitle": "ACT04 · Phản biện", "prompt": "Nhận định: Mọi Persistent Cookie đều là Tracking Cookie. Em đồng ý không? Lấy ví dụ language=vi để giải thích.", "asset": "", "note": "Tracking là mục đích; persistent mô tả vòng đời.", "learner_action": "HS phản biện và nêu hai căn cứ tracking"}, {"id": "A4-03", "section": "ACT04", "title": "Em hãy dạy lại một tình huống", "layout": "recall", "subtitle": "ACT04 · Learning by Teaching", "prompt": "Chọn một trong ba trường hợp rồi giải thích cho bạn mới học trong khoảng 30 giây.", "asset": "", "note": "Không ngắt lời khi HS đang giải thích; GV hỏi thêm một câu phản biện.", "learner_action": "HS dạy lại và recall ba nhóm"}, {"id": "A5-01", "section": "ACT05", "title": "Thử sức độc lập: website câu lạc bộ", "layout": "exit", "subtitle": "ACT05 · EXIT · 8 phút", "prompt": "club.example.org giả lập: theme=dark có hạn 5 ngày; session_id=K25 không đặt hạn lâu dài; có tình huống phân tích.", "asset": "", "note": "Đóng/che nguồn luyện tập; không mở teacher key.", "learner_action": "HS đọc dữ kiện, chuẩn bị làm 3 ô"}, {"id": "A5-02", "section": "ACT05", "title": "EXIT: ba ô A · B · C", "layout": "exit", "subtitle": "ACT05 · Đánh giá độc lập", "prompt": "A: cơ chế mũi tên; B: thời hạn; C: công dụng và quyền riêng tư. Trả lời bằng ký hiệu hoặc câu ngắn.", "asset": "", "note": "Chỉ dùng exit_independent.html/PDF tách riêng trong Skill07; bản layout này không có đáp án.", "learner_action": "HS làm độc lập và nộp bài"}, {"id": "P07-01", "section": "P07", "title": "Nhớ lại bằng sơ đồ trống", "layout": "recall", "subtitle": "Sau giờ · Active Recall và mind-map", "prompt": "Che tài liệu; nói và ghi lại năm từ khóa, sau đó tự vẽ bốn nhánh: cơ chế, loại, công dụng, quyền riêng tư.", "asset": "cookies_mindmap_blank.svg", "note": "Không đếm vào 42 phút nếu lớp đã hoàn thành EXIT.", "learner_action": "HS tự vẽ sơ đồ và nhắc lại"}, {"id": "P07-02", "section": "P07", "title": "Flashcards và dạy lại", "layout": "trio", "subtitle": "Sau giờ · Duy trì trí nhớ", "prompt": "Ôn thuật ngữ; dạy lại vòng đời Cookie; chơi ghép chiều mũi tên và công dụng.", "asset": "", "note": "Trò chơi không dùng thời gian trả lời để đánh giá hiểu biết.", "learner_action": "HS sử dụng flashcards trước buổi sau"}];
let n=0;
const byId=s=>document.getElementById(s);
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function div(cls,content){return '<div class="'+cls+'">'+content+'</div>'}
function card(h,p,l=''){return '<div class="card"><div class="label">'+esc(l)+'</div><h2>'+esc(h)+'</h2><p>'+esc(p)+'</p></div>'}
function imgasset(s){if(!s.asset)return '<div class="noimg">Bản mô phỏng/sơ đồ được hiển thị ở giai đoạn phù hợp<br> sau khi học sinh dự đoán</div>';return '<div class="media"><img src="assets/'+esc(s.asset)+'" alt="Hình minh họa '+esc(s.title)+'" loading="lazy"></div>'}
function contents(s){const t=esc(s.prompt),sub=esc(s.subtitle);switch(s.layout){
case 'cover':return '<div class="two"><div><span class="badge">BÀI HỌC TƯƠNG TÁC</span><p class="lead">'+t+'</p><p class="tiny">Hãy đưa ra một dự đoán bằng lời trước khi bắt đầu bài học.</p></div><div class="browser"><div class="bar"></div><div class="browserbody"><div class="smallcaps">Tùy chọn ngôn ngữ</div><strong>Xin chào!</strong><p>Website vẫn hiển thị Tiếng Việt.</p><span class="badge">language = vi ?</span></div></div></div>';
case 'question':return '<div class="question"><div class="eyebrow">Một câu hỏi trước khi biết đáp án</div><p class="lead">'+t+'</p><div class="example">language=vi</div></div>';
case 'focus':return '<div class="focus"><div><div class="word">COOKIE</div><p class="lead">'+t+'</p></div><div class="feature"><div class="symbol">{···}</div></div></div>';
case 'compare':{let a,b; if(s.section==='ACT01') {a=['Trước lựa chọn','Website chưa biết ngôn ngữ muốn dùng'];b=['Lần quay lại','Website hiển thị Tiếng Việt như lần đã chọn']}else if(s.id==='A2-03'){a=['Đồng ý lưu','Browser có thể lưu nếu cookie đáp ứng điều kiện'];b=['Không chấp nhận','Cookie ấy không được lưu trong trình duyệt']}else if(s.id==='A2-05'){a=['Browser lưu cookie','Trong request phù hợp, cookie ấy có thể được gửi lại'];b=['Browser chặn cookie','Không thể gửi lại chính cookie chưa lưu']}else if(s.id==='A3-02'){a=['Không đặt hạn lâu dài','Xét theo vòng đời phiên trình duyệt'];b=['Thêm hạn 7 ngày','Xét theo thời hạn; tên cart_id không đổi']}else{a=['Vòng đời','Persistent chỉ nói về thời hạn của cookie'];b=['Mục đích','Tracking là mục đích sử dụng cookie']}
return '<div class="compare"><div class="two">'+card(a[0],a[1],'TRƯỜNG HỢP 1')+card(b[0],b[1],'TRƯỜNG HỢP 2')+'</div><p class="layout-foot">'+t+'</p></div>'}
case 'trio':{let a;if(s.section==='ACT04') a=[['SHOP','Quản lý trạng thái giỏ hàng'],['LANGUAGE','Ghi nhớ lựa chọn ngôn ngữ'],['ANALYTICS','Phân tích những lượt xem phù hợp']];else a=[['NHỚ LẠI','Ôn thẻ từ khóa'],['DẠY LẠI','Giải thích sơ đồ Cookie'],['TRÒ CHƠI','Ghép chiều trao đổi và mục đích']];return '<div class="three trio">'+a.map((x,i)=>card(x[0],x[1],'THẺ 0'+(i+1))).join('')+'</div><p class="layout-foot">'+t+'</p>'}
case 'diagram':return '<div class="two"><div>'+imgasset(s)+'</div><div class="box"><div class="label">Nhiệm vụ quan sát</div><p class="lead">'+t+'</p><p class="tiny">Bản hình trống dùng để học sinh tự điền, không chiếu đáp án trước.</p></div></div>';
case 'progressive':return '<div class="progressive">'+imgasset(s)+'<div class="box"><span class="badge">CƠ CHẾ THEO TỪNG BƯỚC</span><p class="lead">'+t+'</p><div class="trybox">Hỏi học sinh “Vì sao?” trước khi hiển thị bước tiếp.</div></div></div>';
case 'practice':return '<div class="progressive"><div class="box"><div class="label">Bảng thao tác</div><p class="lead">'+t+'</p><div class="fakefield"></div><p class="tiny">Vùng tương tác thật được phát triển ở Skill 11. Bản này chỉ minh họa layout.</p></div><div class="box"><div class="label">Phản hồi có điều kiện</div><p>Học sinh lựa chọn hoặc giải thích, sau đó mới nhận phản hồi.</p><p class="tiny">Không hiển thị đáp án tiếp theo ngay khi HS chọn sai.</p><a class="actionlink" href="assets/learning_lab.html" target="_blank" rel="noopener">Mở học liệu Skill 07 gốc</a></div></div>';
case 'timeline':return '<div class="box" style="width:100%"><p class="lead">'+t+'</p><div class="three trio">'+['Đang duyệt','Phiên kết thúc','Ngày hôm sau'].map((x,i)=>card(x,'HS dự đoán trạng thái trước khi xem đáp án','MỐC '+(i+1))).join('')+'</div></div>';
case 'recall':return '<div class="recall"><div class="big"><div class="label">ACTIVE RECALL</div><h2>Không nhìn tài liệu</h2><p class="lead">'+t+'</p></div><div class="box"><div class="label">Sản phẩm học sinh</div><p>1. Nói thành lời</p><p>2. Viết hoặc vẽ vào vở</p><p>3. Tự đối chiếu sau khi hoàn thành</p>'+ (s.asset?'<img src="assets/'+esc(s.asset)+'" alt="Sơ đồ tư duy trống" style="max-width:100%">':'')+'</div></div>';
case 'exit':return '<div style="width:100%"><div class="exitnotice">EXIT ĐỘC LẬP • Đóng nội dung luyện tập; tuyệt đối không hiện lời giải.</div><p class="lead">'+t+'</p><div class="exitgrid">'+card('Ô A – Cơ chế','Mũi tên request, response + Set-Cookie và request có Cookie')+card('Ô B – Thời hạn','Session, persistent và điều kiện cookie còn/hết')+card('Ô C – Ứng dụng','Các nhóm công dụng, tracking và quyền riêng tư')+'</div><p class="tiny">Bản kiểm tra thực tế là tệp exit_independent.html/.pdf riêng trong bộ Skill 07.</p></div>';
default:return '<div class="box">'+t+'</div>'}}
function render(){const s=d[n];document.title=s.title+' • Cookies Skill09 v2';byId('title').textContent=s.title;byId('section').textContent=s.section+' • '+s.layout.toUpperCase();byId('subtitle').textContent=s.subtitle;byId('stage').innerHTML=contents(s);byId('counter').textContent=(n+1)+' / '+d.length;byId('prev').disabled=n===0;byId('next').disabled=n===d.length-1;byId('next').textContent=n===d.length-1?'Đã xem hết':'Tiếp theo →';byId('note').textContent='MỤC TIÊU THAO TÁC: '+s.learner_action+' • Bản prototype UI, chưa có engine chấm/ghi tiến độ.';
const groups=[...new Set(d.map(x=>x.section))];const nav=byId('nav');nav.replaceChildren();groups.forEach(g=>{const b=document.createElement('button');b.className='navbtn '+(s.section===g?'active':'');b.textContent=g==='P00'?'Mở đầu':g==='P07'?'Ôn tập':g;b.onclick=()=>{n=d.findIndex(x=>x.section===g);render()};nav.append(b)});const dots=byId('dots');dots.replaceChildren();d.forEach((x,i)=>{const v=document.createElement('i');v.className=i===n?'active':'';dots.append(v)});
window.scrollTo({top:0,behavior:'instant'});
}
byId('prev').onclick=()=>{if(n>0){n--;render()}};byId('next').onclick=()=>{if(n<d.length-1){n++;render()}};document.addEventListener('keydown',e=>{if(e.target.closest('button,input,textarea,a'))return;if(e.key==='ArrowRight'&&n<d.length-1){n++;render()}if(e.key==='ArrowLeft'&&n>0){n--;render()}});render();
